import { networkInterfaces } from 'node:os';
import { join } from 'node:path';
import * as utils from '@iobroker/adapter-core';
import { type ModelBackend, ModelManagement } from './lib/device-management';
import { type EndpointSettings, escapeHtml, getEndpoints, hostAddresses } from './lib/endpoint';
import { KEEP_FOREVER, keepAliveFor, keepLoadedAction } from './lib/keep-loaded';
import { type ModelInfo, modelOptions, sameModel, toModelInfos } from './lib/models';
import { MODEL_STATES, parseModelCommand, toModelId } from './lib/objects';
import {
    isValidModelName,
    type OllamaChatResponse,
    OllamaClient,
    type OllamaGenerateResponse,
    type OllamaMessage,
    type OllamaRunningModel,
    type OllamaStats,
} from './lib/ollama-client';
import { PendingResults } from './lib/pending-results';
import { RequestQueue } from './lib/queue';
import {
    type RequestDefaults,
    type RequestMetrics,
    shorten,
    toChatRequest,
    toGenerateRequest,
    toMetrics,
} from './lib/requests';
import { findUnusedModels, LAST_USED_RESOLUTION_MS } from './lib/usage';

/** First and maximal delay between two attempts to reach Ollama */
const RETRY_MIN_MS = 2_000;
const RETRY_MAX_MS = 30_000;
/** After this time without answer, the log explains why the adapter is still waiting */
const WAIT_INFO_AFTER_MS = 60_000;
/** Interval of the connection check via /api/ps */
const MONITOR_INTERVAL_MS = 30_000;
/** Timeout of the short requests that only check whether Ollama answers */
const PROBE_TIMEOUT_MS = 5_000;
/** The progress of a download is written at most this often */
const PULL_PROGRESS_INTERVAL_MS = 1_000;
/** Unused models are looked for this often, the first time after this time since the connection */
const CLEANUP_INTERVAL_MS = 60 * 60_000;
/** `chatResult` answers within this time, as the browser drops answers after 30 s */
const MAX_RESULT_WAIT_MS = 25_000;
/** Answers of `chatStart` that nobody fetched are forgotten after this time */
const KEEP_RESULT_MS = 10 * 60_000;
/** If the default model cannot be kept loaded, e.g. as the memory is too small, the next attempt waits this long */
const KEEP_LOADED_RETRY_MS = 10 * 60_000;

type Status = 'starting' | 'ready' | 'busy' | 'error' | 'stopped';

/** The part of `@iobroker/plugin-docker` that is used here */
interface DockerPlugin {
    getDockerManager(): {
        getDockerDaemonInfo(): Promise<{ daemonRunning?: boolean; version?: string }>;
    } | null;
}

function errorText(error: unknown): string {
    return error instanceof Error ? error.message : String(error);
}

/**
 * The model named in a message of sendTo
 *
 * @param message e.g. `{ model: "qwen3:4b" }`
 */
function getModel(message: unknown): string {
    const model = message && typeof message === 'object' ? (message as { model?: unknown }).model : undefined;
    if (typeof model !== 'string' || !model.trim()) {
        throw new Error('The message has to name the model, e.g. { model: "qwen3:4b" }');
    }
    return model.trim();
}

class AiServer extends utils.Adapter {
    #client: OllamaClient | null = null;
    #connected = false;
    #unloading = false;
    #retryTimer: ioBroker.Timeout | undefined;
    #monitorTimer: ioBroker.Interval | undefined;
    #monitorRunning = false;
    #subscribed = false;
    /** Names of the models by object ID, as of the last refresh */
    #models = new Map<string, string>();
    /** Refreshes run one after another, so that two of them do not create and delete the same objects */
    #refreshQueue: Promise<unknown> = Promise.resolve();
    /** The model being downloaded. Only one download runs at a time, as there is one progress state */
    #pulling: string | null = null;
    /** Limits the requests to the model (chat, generate) to `parallel` at a time */
    #queue: RequestQueue | null = null;
    /** Answers of `chatStart`, until they are fetched with `chatResult` */
    #pendingChats: PendingResults<Record<string, unknown>> | null = null;
    /** Value of `info.status` */
    #status: Status = 'starting';
    /** Version of Ollama, as of the last connection */
    #version = '';
    /** Number of running requests started via `chat.prompt` */
    #stateChats = 0;
    /** Time of the last use of the models by object ID, as in the states `models.<id>.lastUsed` */
    #lastUsed = new Map<string, number>();
    /** Time of the last search for unused models */
    #lastCleanup = 0;
    /** The default model was unloaded on purpose: it is not loaded again until it is loaded or used otherwise */
    #keepLoadedPaused = false;
    /** After a failed attempt to keep the default model loaded, the next one waits until this time */
    #keepLoadedRetryAt = 0;

    public constructor(options: Partial<utils.AdapterOptions> = {}) {
        super({
            ...options,
            name: 'ai-server',
        });
        this.on('ready', this.onReady.bind(this));
        this.on('stateChange', this.onStateChange.bind(this));
        this.on('message', this.onMessage.bind(this));
        this.on('unload', this.onUnload.bind(this));
    }

    /**
     * Is called when databases are connected and adapter received configuration.
     * The container itself is started by plugin-docker (see docker-compose.yaml), not by the adapter.
     * The plugin is initialized before this method is called, so a missing image is already pulled.
     */
    private async onReady(): Promise<void> {
        try {
            // the texts of the device manager are in the translations of the instance settings
            await utils.I18n.init(join(__dirname, '..', 'admin'), this);
        } catch (error) {
            this.log.warn(`Cannot read the translations: ${errorText(error)}`);
        }
        // the models in the device manager of the admin: it receives the messages "dm:*" by itself
        new ModelManagement(this, this.#modelBackend());

        await this.setState('info.connection', false, true);
        await this.#setStatus('starting');
        this.#queue = new RequestQueue({
            parallel: this.config.parallel,
            maxQueue: this.config.maxQueue,
            onChange: running => this.#onQueueChange(running),
        });
        this.#pendingChats = new PendingResults({
            keepMs: KEEP_RESULT_MS,
            timers: {
                setTimeout: (callback, ms) => this.setTimeout(callback, ms),
                clearTimeout: handle => this.clearTimeout(handle as ioBroker.Timeout | undefined),
            },
        });

        const baseUrl = this.#getBaseUrl();
        if (!baseUrl) {
            await this.#setError(
                `Invalid URL of the external Ollama server: "${this.config.externalUrl}". Expected e.g. http://192.168.1.50:11434`,
            );
            return;
        }

        if (this.config.backend === 'docker') {
            if (this.config.bind === '0.0.0.0') {
                this.log.warn(
                    `Ollama is reachable on port ${this.config.port} from the whole network. Ollama has no authentication: everyone in the network can use and change it.`,
                );
            }
            const dockerError = await this.#checkDocker();
            if (dockerError) {
                await this.#setError(dockerError);
                return;
            }
        }

        this.#client = new OllamaClient({
            baseUrl,
            timeoutMs: this.#requestTimeoutMs(),
            timers: {
                setTimeout: (callback, ms) => this.setTimeout(callback, ms),
                clearTimeout: handle => this.clearTimeout(handle as ioBroker.Timeout | undefined),
            },
        });
        this.log.info(`Waiting for Ollama at ${baseUrl}`);
        this.#waitForOllama();
    }

    /**
     * Is called when adapter shuts down - callback has to be called under any circumstances!
     *
     * @param callback - Callback function
     */
    private async onUnload(callback: () => void): Promise<void> {
        try {
            this.#unloading = true;
            this.#queue?.clear(new Error('The adapter is stopping'));
            this.#client?.abortAll();
            this.#pendingChats?.clear();
            this.#stopMonitor();
            this.clearTimeout(this.#retryTimer);
            await this.setState('info.connection', false, true);
            await this.#setStatus('stopped');
        } catch (error) {
            this.log.error(`Error during unloading: ${errorText(error)}`);
        } finally {
            callback();
        }
    }

    /**
     * Commands written into the states: `control.pull`, `control.refresh` and the buttons of the models
     *
     * @param id full state ID
     * @param state the new state, only commands (`ack: false`) are handled
     */
    private async onStateChange(id: string, state: ioBroker.State | null | undefined): Promise<void> {
        if (!state || state.ack) {
            return;
        }
        const localId = id.substring(this.namespace.length + 1);
        try {
            if (localId === 'control.pull') {
                const model = typeof state.val === 'string' ? state.val.trim() : '';
                if (model) {
                    // acknowledged by the download itself
                    void this.#startPull(model);
                } else {
                    await this.setState(localId, '', true);
                }
            } else if (localId === 'control.refresh') {
                await this.setState(localId, state.val, true);
                await this.#refreshModels();
            } else if (localId === 'chat.model' || localId === 'chat.system' || localId === 'chat.think') {
                // read when the next prompt is written
                await this.setState(localId, state.val, true);
            } else if (localId === 'chat.prompt') {
                const prompt = typeof state.val === 'string' ? state.val : '';
                await this.setState(localId, prompt, true);
                if (prompt.trim()) {
                    await this.#chatFromStates(prompt);
                }
            } else {
                const command = parseModelCommand(localId);
                if (!command || !state.val) {
                    return;
                }
                await this.setState(localId, state.val, true);
                const model = this.#models.get(command.id);
                if (!model) {
                    throw new Error('Ollama does not have this model any more');
                }
                await this.#setLoaded(model, command.command === 'load');
            }
        } catch (error) {
            await this.#reportError(`${localId}: ${errorText(error)}`);
        }
    }

    /**
     * The sendTo API. Every message with a callback is answered, with `{ result }` or `{ error }`
     *
     * @param obj the message
     */
    private async onMessage(obj: ioBroker.Message): Promise<void> {
        // the messages of the device manager are answered by ModelManagement
        if (!obj?.command || obj.command.startsWith('dm:')) {
            return;
        }
        let answer: unknown;
        if (obj.command === 'getModelOptions') {
            // the choice of the default model in the instance settings expects a plain list
            answer = modelOptions(await this.#refreshModels().catch(() => []));
        } else if (obj.command === 'getEndpointInfo') {
            // the control textSendTo in the instance settings expects { text } as it is
            answer = this.#endpointInfo(obj.message);
        } else {
            try {
                answer = { result: await this.#handleCommand(obj.command, obj.message) };
            } catch (error) {
                answer = { error: errorText(error) };
            }
        }
        if (obj.callback) {
            this.sendTo(obj.from, obj.command, answer, obj.callback);
        }
    }

    /**
     * Execute a command of the sendTo API
     *
     * @param command name of the command
     * @param message parameters of the command
     */
    async #handleCommand(command: string, message: unknown): Promise<unknown> {
        switch (command) {
            case 'listModels':
                return this.#refreshModels();

            case 'pull':
                void this.#startPull(getModel(message));
                return { started: true };

            case 'deleteModel':
                await this.#deleteModel(getModel(message));
                return { deleted: true };

            case 'loadModel':
                await this.#setLoaded(getModel(message), true);
                return { loaded: true };

            case 'unloadModel':
                await this.#setLoaded(getModel(message), false);
                return { unloaded: true };

            case 'chat':
                return this.#chatAnswer(message);

            case 'chatStart': {
                // for clients that drop an answer after a while, like the browser after 30 s: they fetch it in parts
                if (!this.#pendingChats) {
                    throw new Error('The adapter is not ready yet');
                }
                return { id: this.#pendingChats.start(this.#chatAnswer(message)) };
            }

            case 'chatResult': {
                const { id, wait } = (message || {}) as { id?: unknown; wait?: unknown };
                if (typeof id !== 'string' || !this.#pendingChats) {
                    throw new Error('The message has to contain the "id" returned by chatStart');
                }
                const waitMs = typeof wait === 'number' && wait >= 0 ? Math.min(wait, MAX_RESULT_WAIT_MS) : 0;
                const answer = await this.#pendingChats.wait(id, waitMs);
                return answer.done ? { done: true, ...answer.result } : { done: false };
            }

            case 'generate': {
                const { response, metrics } = await this.#generate(message);
                return {
                    response: response.response,
                    ...(response.thinking ? { thinking: response.thinking } : {}),
                    model: response.model,
                    durationMs: metrics.durationMs,
                    promptTokens: metrics.promptTokens,
                    completionTokens: metrics.completionTokens,
                    tokensPerSecond: metrics.tokensPerSecond,
                };
            }

            case 'status':
                return {
                    connected: this.#connected,
                    status: this.#status,
                    version: this.#version,
                    baseUrl: this.#client?.baseUrl ?? this.#getBaseUrl(),
                    loadedModels: await this.#loadedModels(),
                };

            case 'getEndpoint': {
                const baseUrl = this.#client?.baseUrl ?? this.#getBaseUrl();
                if (!baseUrl) {
                    throw new Error('The URL of the external Ollama server is invalid');
                }
                return { ollama: baseUrl, openai: `${baseUrl}/v1` };
            }

            default:
                throw new Error(`Unknown command "${command}"`);
        }
    }

    /** Timeout of a request to the model in ms */
    #requestTimeoutMs(): number {
        return (Number(this.config.requestTimeout) || 300) * 1000;
    }

    /** What the device manager of the admin needs from the adapter */
    #modelBackend(): ModelBackend {
        return {
            listModels: () => this.#refreshModels(),
            getChannelId: name => {
                const id = this.#findModelId(name);
                return id ? `${this.namespace}.models.${id}` : undefined;
            },
            getLastUsed: name => {
                const id = this.#findModelId(name);
                return id ? this.#lastUsed.get(id) : undefined;
            },
            getSettings: () => ({
                defaultModel: this.config.defaultModel || '',
                deleteUnusedDays: Number(this.config.deleteUnusedDays) || 0,
                requestTimeoutMs: this.#requestTimeoutMs(),
            }),
            setLoaded: (name, load) => this.#setLoaded(name, load),
            deleteModel: name => this.#deleteModel(name),
            pull: async (name, onProgress) => {
                await this.#startPull(name, onProgress);
            },
        };
    }

    /** The URL of the Ollama API without trailing slash, or null if the configured URL is invalid */
    #getBaseUrl(): string | null {
        if (this.config.backend === 'external') {
            const url = (this.config.externalUrl || '').trim().replace(/\/+$/, '');
            try {
                const parsed = new URL(url);
                return parsed.protocol === 'http:' || parsed.protocol === 'https:' ? url : null;
            } catch {
                return null;
            }
        }
        // Docker publishes the port on the bind address only. 0.0.0.0 includes the loopback address.
        const host = this.config.bind && this.config.bind !== '0.0.0.0' ? this.config.bind : '127.0.0.1';
        return `http://${host}:${Number(this.config.port) || 11434}`;
    }

    /**
     * The addresses of Ollama for the instance settings, as HTML
     *
     * @param message backend, bind address, port and URL of the external server as in the form, maybe not saved yet
     */
    #endpointInfo(message: unknown): { text: string; icon: string } {
        const settings: EndpointSettings = message && typeof message === 'object' ? message : this.config;
        const endpoints = getEndpoints(settings, hostAddresses(networkInterfaces()));
        const t = (key: string, ...args: string[]): string => escapeHtml(utils.I18n.translate(key, ...args));
        if (!endpoints) {
            return { text: t('endpoint_invalid'), icon: 'no-connection' };
        }
        // 127.0.0.1 in a link would lead to the computer of the browser
        const link = (url: string): string =>
            endpoints.localOnly
                ? `<code>${escapeHtml(url)}</code>`
                : // the default blue of a link can hardly be read on the dark theme
                  `<a href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer" style="color: inherit">${escapeHtml(url)}</a>`;
        const lines = [
            `<b>${t('Ollama API')}:</b> ${endpoints.urls.map(link).join(', ')}`,
            `<b>${t('OpenAI-compatible API')}:</b> ${endpoints.urls.map(url => `<code>${escapeHtml(url)}/v1</code>`).join(', ')}`,
            t('endpoint_noKey'),
        ];
        if (endpoints.localOnly) {
            lines.push(t('endpoint_localOnly', this.host || ''));
            if (settings.backend !== 'external') {
                lines.push(t('endpoint_bindHint'));
            }
        }
        return { text: lines.join('<br>'), icon: 'connection' };
    }

    /** Check that plugin-docker can run the container. Returns the error text, or null if everything is fine */
    async #checkDocker(): Promise<string | null> {
        if (!this.config.dockerCpu && !this.config.dockerRocm) {
            return 'Backend "docker" is selected, but no Docker service is enabled. Please open the instance settings and save them again.';
        }
        const plugin = this.getPluginInstance('docker') as unknown as DockerPlugin | null;
        const manager = plugin?.getDockerManager?.();
        if (!manager) {
            return 'The Docker plugin is not active, so the Ollama container cannot be started. Select the backend "External Ollama server" in the instance settings to use an existing server.';
        }
        const info = await manager.getDockerDaemonInfo().catch(() => null);
        if (!info?.daemonRunning) {
            return 'Docker is not available on this host. Install Docker Engine 20.10 or newer and add the user "iobroker" to the group "docker", or select the backend "External Ollama server" in the instance settings.';
        }
        this.log.debug(`Docker ${info.version || ''} is available`);
        return null;
    }

    /**
     * Ask /api/version until Ollama answers. On the first start the container may need a while
     * until it listens, and an external server may be down. There is no upper limit.
     */
    #waitForOllama(): void {
        const started = Date.now();
        let delay = RETRY_MIN_MS;
        let infoLogged = false;
        const attempt = async (): Promise<void> => {
            this.#retryTimer = undefined;
            if (this.#unloading || !this.#client) {
                return;
            }
            let version: string;
            try {
                version = await this.#client.getVersion(PROBE_TIMEOUT_MS);
            } catch (error) {
                if (this.#unloading) {
                    return;
                }
                if (!infoLogged && Date.now() - started >= WAIT_INFO_AFTER_MS) {
                    infoLogged = true;
                    this.log.info(
                        this.config.backend === 'docker'
                            ? `Ollama does not answer yet (${errorText(error)}). The container may still be starting, the adapter keeps trying.`
                            : `The external Ollama server does not answer yet (${errorText(error)}). The adapter keeps trying.`,
                    );
                } else {
                    this.log.debug(`Ollama does not answer yet: ${errorText(error)}`);
                }
                this.#retryTimer = this.setTimeout(() => void attempt(), delay);
                delay = Math.min(delay * 2, RETRY_MAX_MS);
                return;
            }
            await this.#onConnected(version);
        };
        void attempt();
    }

    async #onConnected(version: string): Promise<void> {
        this.#connected = true;
        this.#version = version;
        await this.setState('info.backendVersion', version, true);
        await this.setState('info.connection', true, true);
        await this.#setStatus(this.#queue?.running ? 'busy' : 'ready');
        this.log.info(`Connected to Ollama ${version} at ${this.#client?.baseUrl}`);

        let models: ModelInfo[] | null = null;
        try {
            models = await this.#refreshModels();
        } catch (error) {
            await this.#reportError(`Cannot read the models: ${errorText(error)}`);
        }
        if (!this.#subscribed) {
            this.#subscribed = true;
            await this.subscribeStatesAsync('control.pull');
            await this.subscribeStatesAsync('control.refresh');
            await this.subscribeStatesAsync('models.*.load');
            await this.subscribeStatesAsync('models.*.unload');
            await this.subscribeStatesAsync('chat.model');
            await this.subscribeStatesAsync('chat.system');
            await this.subscribeStatesAsync('chat.think');
            await this.subscribeStatesAsync('chat.prompt');
        }
        this.#monitorTimer = this.setInterval(() => void this.#monitor(), MONITOR_INTERVAL_MS);
        // give the monitor time to see which models are in use before anything is deleted
        this.#lastCleanup = Date.now();
        if (models) {
            this.#ensureDefaultModel(models);
        }
        if (this.#keptModel()) {
            // load the default model at once, not only with the next check
            void this.#monitor();
        }
    }

    /**
     * Check the connection, update `loaded` and delete unused models regularly.
     * If Ollama does not answer, wait for it again.
     */
    async #monitor(): Promise<void> {
        if (this.#monitorRunning || !this.#client || !this.#connected) {
            return;
        }
        this.#monitorRunning = true;
        try {
            let running: OllamaRunningModel[];
            try {
                running = await this.#client.listRunningModels(PROBE_TIMEOUT_MS);
            } catch (error) {
                if (!this.#unloading) {
                    await this.#onDisconnected(error);
                }
                return;
            }
            await this.#updateLoaded(running);
            await this.#keepDefaultLoaded(running);
            await this.#deleteUnusedModels(running);
        } catch (error) {
            this.log.warn(`Cannot update the models: ${errorText(error)}`);
        } finally {
            this.#monitorRunning = false;
        }
    }

    async #onDisconnected(error: unknown): Promise<void> {
        this.#stopMonitor();
        this.#connected = false;
        await this.setState('info.connection', false, true);
        await this.#setError(`Connection to Ollama lost: ${errorText(error)}`, 'warn');
        this.#waitForOllama();
    }

    #stopMonitor(): void {
        if (this.#monitorTimer) {
            this.clearInterval(this.#monitorTimer);
            this.#monitorTimer = undefined;
        }
    }

    /** The client, if Ollama is reachable. Commands fail with a clear message otherwise */
    #requireClient(): OllamaClient {
        if (!this.#client) {
            throw new Error('Ollama is not available, see info.lastError');
        }
        if (!this.#connected) {
            throw new Error(`Ollama does not answer at ${this.#client.baseUrl}`);
        }
        return this.#client;
    }

    /** Read the models from Ollama and bring the objects below `models` up to date */
    #refreshModels(): Promise<ModelInfo[]> {
        const run = this.#refreshQueue.then(() => this.#syncModels());
        this.#refreshQueue = run.catch(() => undefined);
        return run;
    }

    async #syncModels(): Promise<ModelInfo[]> {
        const client = this.#requireClient();
        const [models, running] = await Promise.all([client.listModels(), client.listRunningModels()]);
        const infos = toModelInfos(models, running);
        const current = new Map<string, string>();
        const now = Date.now();
        for (const info of infos) {
            const id = toModelId(info.name, this.FORBIDDEN_CHARS);
            const other = current.get(id);
            if (other) {
                this.log.warn(
                    `The models ${other} and ${info.name} get the same object ID "${id}", only ${other} is shown`,
                );
                continue;
            }
            current.set(id, info.name);
            if (this.#models.get(id) !== info.name) {
                await this.extendObject(`models.${id}`, { type: 'channel', common: { name: info.name }, native: {} });
                for (const [key, common] of Object.entries(MODEL_STATES)) {
                    await this.extendObject(`models.${id}.${key}`, { type: 'state', common, native: {} });
                }
            }
            for (const [key, value] of Object.entries(info)) {
                await this.setStateChangedAsync(`models.${id}.${key}`, value as ioBroker.StateValue, true);
            }
            if (!this.#lastUsed.has(id)) {
                // a new model counts as used when the adapter sees it the first time
                const state = await this.getStateAsync(`models.${id}.lastUsed`);
                const known = typeof state?.val === 'number' && state.val > 0 ? state.val : 0;
                this.#lastUsed.set(id, known || now);
                if (!known) {
                    await this.setState(`models.${id}.lastUsed`, now, true);
                }
            }
            if (info.loaded) {
                await this.#markUsed(id, now);
            }
        }

        // Also models deleted while the adapter was not running
        const prefix = `${this.namespace}.models.`;
        const channels = await this.getObjectViewAsync('system', 'channel', {
            startkey: prefix,
            endkey: `${prefix}香`,
        });
        for (const row of channels.rows) {
            const id = row.id.substring(prefix.length);
            if (!id.includes('.') && !current.has(id)) {
                this.log.debug(`Model ${id} does not exist any more, deleting its objects`);
                await this.delObjectAsync(`models.${id}`, { recursive: true });
                this.#lastUsed.delete(id);
            }
        }
        this.#models = current;
        return infos;
    }

    /**
     * Update `loaded` of all models. A loaded model that is not known yet was downloaded without the adapter,
     * then the whole list is read again.
     *
     * @param running the answer of /api/ps
     */
    async #updateLoaded(running: OllamaRunningModel[]): Promise<void> {
        const known = [...this.#models.values()];
        if (running.some(item => !known.some(name => sameModel(name, item.name || item.model)))) {
            await this.#refreshModels();
            return;
        }
        for (const [id, name] of this.#models) {
            const loaded = running.some(item => sameModel(item.name || item.model, name));
            await this.setStateChangedAsync(`models.${id}.loaded`, loaded, true);
            if (loaded) {
                await this.#markUsed(id);
            }
        }
    }

    /**
     * Object ID of a downloaded model
     *
     * @param name name of the model, as given or as Ollama reports it
     */
    #findModelId(name: string): string | undefined {
        for (const [id, known] of this.#models) {
            if (sameModel(known, name)) {
                return id;
            }
        }
        return undefined;
    }

    /**
     * Remember the use of a model in `models.<id>.lastUsed`. A model that stays loaded is written every few minutes only.
     *
     * @param id object ID of the model
     * @param now time of the use
     */
    async #markUsed(id: string, now = Date.now()): Promise<void> {
        if (now - (this.#lastUsed.get(id) ?? 0) < LAST_USED_RESOLUTION_MS) {
            return;
        }
        this.#lastUsed.set(id, now);
        await this.setState(`models.${id}.lastUsed`, now, true);
    }

    /**
     * A request was answered by the model: it is in use
     *
     * @param name the model as named in the answer
     */
    #noteUse(name: string): void {
        const id = this.#findModelId(name);
        if (id) {
            this.#markUsed(id).catch(error => this.log.debug(`Cannot write the last use: ${errorText(error)}`));
        }
    }

    /**
     * Delete a model from the disk of Ollama
     *
     * @param model name of the model
     */
    async #deleteModel(model: string): Promise<void> {
        await this.#requireClient().deleteModel(model);
        this.log.info(`Model ${model} deleted`);
        await this.#refreshModels();
    }

    /**
     * Delete the models nobody used for `deleteUnusedDays` days, at most once per hour.
     * The default model and a model being downloaded are kept.
     *
     * @param running the answer of /api/ps
     */
    async #deleteUnusedModels(running: OllamaRunningModel[]): Promise<void> {
        const days = Number(this.config.deleteUnusedDays) || 0;
        const now = Date.now();
        if (days <= 0 || now - this.#lastCleanup < CLEANUP_INTERVAL_MS) {
            return;
        }
        this.#lastCleanup = now;
        const models = [...this.#models].map(([id, name]) => ({
            name,
            loaded: running.some(item => sameModel(item.name || item.model, name)),
            lastUsed: this.#lastUsed.get(id),
        }));
        const unused = findUnusedModels(models, now, days, [this.config.defaultModel || '', this.#pulling || '']);
        for (const model of unused) {
            try {
                await this.#requireClient().deleteModel(model);
                this.log.info(`Model ${model} deleted, because it was not used for ${days} days`);
            } catch (error) {
                await this.#reportError(`Cannot delete the unused model ${model}: ${errorText(error)}`);
            }
        }
        if (unused.length) {
            await this.#refreshModels();
        }
    }

    /**
     * Load a model into memory or unload it
     *
     * @param model name of the model
     * @param load true to load, false to unload
     */
    async #setLoaded(model: string, load: boolean): Promise<void> {
        const client = this.#requireClient();
        const kept = !!this.#keptModel() && sameModel(model, this.#keptModel());
        if (load) {
            await client.loadModel(model, keepAliveFor(model, this.config.keepAlive, this.#keptModel()));
        } else {
            await client.unloadModel(model);
        }
        this.log.info(`Model ${model} ${load ? 'loaded' : 'unloaded'}`);
        if (kept) {
            this.#keepLoadedPaused = !load;
            if (!load) {
                this.log.info(`The default model ${model} stays unloaded until it is loaded again or used`);
            }
        }
        await this.#updateLoaded(await client.listRunningModels());
    }

    /** The model to keep loaded: the default model if "Keep the default model loaded" is on, else empty */
    #keptModel(): string {
        return this.config.keepDefaultLoaded ? (this.config.defaultModel || '').trim() : '';
    }

    /**
     * Keep the default model loaded, if so configured. Load it again when Ollama unloaded it, e.g. after another model
     * was used, and load it for good again when a request of another client set a time to unload it.
     *
     * @param running the answer of /api/ps
     */
    async #keepDefaultLoaded(running: OllamaRunningModel[]): Promise<void> {
        const model = this.#keptModel();
        if (!model || !this.#findModelId(model)) {
            // not downloaded (yet)
            return;
        }
        if (running.some(item => sameModel(item.name || item.model, model))) {
            this.#keepLoadedPaused = false;
        }
        const action = keepLoadedAction(model, running);
        if (
            action === 'none' ||
            this.#keepLoadedPaused ||
            this.#queue?.running ||
            Date.now() < this.#keepLoadedRetryAt
        ) {
            return;
        }
        const client = this.#requireClient();
        try {
            if (action === 'load') {
                this.log.info(`Loading the default model ${model}, it stays loaded`);
            } else {
                this.log.debug(`The default model ${model} would be unloaded some time, loading it for good`);
            }
            await client.loadModel(model, KEEP_FOREVER);
            if (action === 'load') {
                await this.#updateLoaded(await client.listRunningModels());
            }
        } catch (error) {
            this.#keepLoadedRetryAt = Date.now() + KEEP_LOADED_RETRY_MS;
            await this.#reportError(
                `Cannot keep the default model ${model} loaded, trying again in ${KEEP_LOADED_RETRY_MS / 60_000} minutes: ${errorText(error)}`,
            );
        }
    }

    /**
     * Download the default model if Ollama does not have it, e.g. on the first start
     *
     * @param models the downloaded models
     */
    #ensureDefaultModel(models: ModelInfo[]): void {
        const model = (this.config.defaultModel || '').trim();
        if (!model || this.#pulling || models.some(item => sameModel(item.name, model))) {
            return;
        }
        this.log.info(`The default model ${model} is not downloaded yet, downloading it now`);
        try {
            void this.#startPull(model);
        } catch (error) {
            void this.#reportError(`Cannot download the default model: ${errorText(error)}`);
        }
    }

    /**
     * Start the download of a model. Its progress goes to `control.pullProgress`, the result to the log.
     * Throws at once if the download cannot start.
     *
     * @param model name of the model
     * @param onProgress gets the progress in percent (null if the message has none) and the status of Ollama
     * @returns the download, which fails if the download fails. The error is reported anyway, so there is no need to wait.
     */
    #startPull(model: string, onProgress?: (percent: number | null, status: string) => void): Promise<void> {
        const client = this.#requireClient();
        if (!isValidModelName(model)) {
            throw new Error(`Invalid model name: ${JSON.stringify(model)}`);
        }
        if (this.#pulling) {
            throw new Error(`The download of ${this.#pulling} is still running`);
        }
        this.#pulling = model;
        const download = this.#pull(client, model, onProgress);
        void download.catch(() => undefined);
        return download;
    }

    async #pull(
        client: OllamaClient,
        model: string,
        onProgress?: (percent: number | null, status: string) => void,
    ): Promise<void> {
        let lastWrite = 0;
        let lastPercent = 0;
        const writeProgress = (percent: number): void => {
            this.setState('control.pullProgress', percent, true).catch(error =>
                this.log.debug(`Cannot write the progress: ${errorText(error)}`),
            );
        };
        try {
            await this.setState('control.pull', model, true);
            await this.setState('control.pullProgress', 0, true);
            this.log.info(`Downloading model ${model}`);
            await client.pull(model, (status, percent) => {
                onProgress?.(percent, status.status ?? '');
                const now = Date.now();
                if (percent === null || percent === lastPercent || now - lastWrite < PULL_PROGRESS_INTERVAL_MS) {
                    return;
                }
                lastWrite = now;
                lastPercent = percent;
                writeProgress(percent);
            });
            await this.setState('control.pullProgress', 100, true);
            this.log.info(`Model ${model} downloaded`);
        } catch (error) {
            if (!this.#unloading) {
                await this.setState('control.pullProgress', 0, true);
                await this.#reportError(`Cannot download model ${model}: ${errorText(error)}`);
            }
            throw error;
        } finally {
            this.#pulling = null;
        }
        await this.#refreshModels().catch(error => this.#reportError(`Cannot read the models: ${errorText(error)}`));
    }

    /** Default model and keep-alive for the requests */
    #requestDefaults(): RequestDefaults {
        return { model: this.config.defaultModel, keepAlive: this.config.keepAlive, keptModel: this.#keptModel() };
    }

    /**
     * Send a chat to the model
     *
     * @param message the message of `sendTo('chat')`
     */
    async #chat(message: unknown): Promise<{ response: OllamaChatResponse; metrics: RequestMetrics }> {
        const client = this.#requireClient();
        const request = toChatRequest(message, this.#requestDefaults());
        this.log.debug(`Chat with ${request.model}: ${shorten(request.messages[request.messages.length - 1].content)}`);
        const result = await this.#runRequest(() => client.chat(request));
        this.#noteUse(result.response.model || request.model);
        this.log.debug(
            `Answer of ${result.response.model} after ${result.metrics.durationMs} ms: ${shorten(result.response.message?.content ?? '')}`,
        );
        return result;
    }

    /**
     * Send a chat to the model and build the answer of `sendTo('chat')`
     *
     * @param message the message of `sendTo('chat')`
     */
    async #chatAnswer(message: unknown): Promise<Record<string, unknown>> {
        const { response, metrics } = await this.#chat(message);
        return {
            message: response.message,
            model: response.model,
            durationMs: metrics.durationMs,
            promptTokens: metrics.promptTokens,
            completionTokens: metrics.completionTokens,
            tokensPerSecond: metrics.tokensPerSecond,
        };
    }

    /**
     * Let the model complete a prompt
     *
     * @param message the message of `sendTo('generate')`
     */
    async #generate(message: unknown): Promise<{ response: OllamaGenerateResponse; metrics: RequestMetrics }> {
        const client = this.#requireClient();
        const request = toGenerateRequest(message, this.#requestDefaults());
        this.log.debug(`Generate with ${request.model}: ${shorten(request.prompt ?? '')}`);
        const result = await this.#runRequest(() => client.generate(request));
        this.#noteUse(result.response.model || request.model);
        this.log.debug(
            `Answer of ${result.response.model} after ${result.metrics.durationMs} ms: ${shorten(result.response.response ?? '')}`,
        );
        return result;
    }

    /**
     * Run a request to the model in the queue, measure it and write the metrics
     *
     * @param request the request to Ollama
     */
    async #runRequest<T extends OllamaStats>(
        request: () => Promise<T>,
    ): Promise<{ response: T; metrics: RequestMetrics }> {
        if (!this.#queue) {
            throw new Error('The adapter is not ready yet');
        }
        const { response, durationMs } = await this.#queue.run(async () => {
            const started = Date.now();
            const response = await request();
            return { response, durationMs: Date.now() - started };
        });
        const metrics = toMetrics(response, durationMs);
        await this.setState('metrics.lastDuration', metrics.durationMs, true);
        await this.setState('metrics.tokensPerSecond', metrics.tokensPerSecond, true);
        await this.setState('metrics.promptTokens', metrics.promptTokens, true);
        await this.setState('metrics.completionTokens', metrics.completionTokens, true);
        return { response, metrics };
    }

    /**
     * A prompt written into `chat.prompt`: a single question without history, with the model of `chat.model`
     * and the system prompt of `chat.system`. The answer goes to `chat.response`.
     * Thinking is switched off unless `chat.think` is set: on a small machine it takes many times longer.
     *
     * @param prompt the question
     */
    async #chatFromStates(prompt: string): Promise<void> {
        const model = await this.getStateAsync('chat.model');
        const system = await this.getStateAsync('chat.system');
        const think = await this.getStateAsync('chat.think');
        this.#stateChats++;
        await this.setState('chat.running', true, true);
        try {
            const { response } = await this.#chat({
                model: typeof model?.val === 'string' ? model.val : '',
                system: typeof system?.val === 'string' && system.val.trim() ? system.val : undefined,
                messages: [{ role: 'user', content: prompt }] satisfies OllamaMessage[],
                think: !!think?.val,
            });
            await this.setState('chat.response', response.message?.content ?? '', true);
        } finally {
            this.#stateChats--;
            if (!this.#stateChats && !this.#unloading) {
                await this.setState('chat.running', false, true);
            }
        }
    }

    /**
     * `info.status` is `busy` while requests to the model run
     *
     * @param running number of running requests
     */
    #onQueueChange(running: number): void {
        if (!this.#connected || this.#unloading) {
            return;
        }
        const status: Status = running ? 'busy' : 'ready';
        if (status !== this.#status) {
            this.#setStatus(status).catch(error => this.log.debug(`Cannot write the status: ${errorText(error)}`));
        }
    }

    /** Names of the models in memory, empty if Ollama does not answer */
    async #loadedModels(): Promise<string[]> {
        if (!this.#client || !this.#connected) {
            return [];
        }
        try {
            const running = await this.#client.listRunningModels(PROBE_TIMEOUT_MS);
            return running.map(item => item.name || item.model);
        } catch {
            return [];
        }
    }

    async #setStatus(status: Status): Promise<void> {
        this.#status = status;
        await this.setState('info.status', status, true);
    }

    /**
     * Ollama cannot be used: log the reason and set the status to `error`
     *
     * @param message the reason
     * @param level log level
     */
    async #setError(message: string, level: 'error' | 'warn' = 'error'): Promise<void> {
        this.log[level](message);
        await this.setState('info.lastError', message, true);
        await this.#setStatus('error');
    }

    /**
     * A single command failed, Ollama itself still works: log the reason, the status stays
     *
     * @param message the reason
     */
    async #reportError(message: string): Promise<void> {
        this.log.error(message);
        await this.setState('info.lastError', message, true);
    }
}

if (require.main !== module) {
    // Export the constructor in compact mode
    module.exports = (options: Partial<utils.AdapterOptions> | undefined) => new AiServer(options);
} else {
    // otherwise start the instance directly
    (() => new AiServer())();
}
